-- ============================================================================
-- Migración 001 · Esquema inicial completo (PostgreSQL 18)
-- Sistema de Gestión de Estacionamiento — Módulo 0
--
-- Convenciones:
--   * Todo el dinero es NUMERIC(14,2).
--   * Borrado lógico con eliminado_en timestamptz (gastos_compras, movimientos,
--     pagos_alquiler, recibos, deudas, contratos_alquiler, percepciones_iibb,
--     clientes, vehiculos, plazas, tarifas).
--   * Claves: integer GENERATED BY DEFAULT AS IDENTITY.
--   * Tiempos: timestamp with time zone.
--   * contratos_alquiler.estado: SOLO ('activo','finalizado','cancelado').
--
-- Aplicar con: npm run migrate  (registra versión + checksum en schema_migrations)
-- ============================================================================

-- btree_gist: necesario para el EXCLUDE de contratos solapados (plaza_id con =)
CREATE EXTENSION IF NOT EXISTS btree_gist;

-- Registro de migraciones (el runner también la asegura por si falta)
CREATE TABLE IF NOT EXISTS schema_migrations (
    version    text PRIMARY KEY,
    checksum   text,
    applied_at timestamp with time zone NOT NULL DEFAULT now()
);

-- ----------------------------------------------------------------------------
-- Clientes
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS clientes (
    id             integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre         varchar(100) NOT NULL,
    documento      varchar(20),
    email          varchar(100),
    telefono       varchar(20),
    saldo_actual   numeric(14,2) NOT NULL DEFAULT 0 CHECK (saldo_actual >= 0),
    fecha_registro timestamp with time zone NOT NULL DEFAULT now(),
    estado         varchar(20) NOT NULL DEFAULT 'activo'
                   CHECK (estado IN ('activo','inactivo')),
    eliminado_en   timestamp with time zone
);

CREATE INDEX IF NOT EXISTS idx_clientes_nombre ON clientes (nombre);
CREATE INDEX IF NOT EXISTS idx_clientes_estado ON clientes (estado) WHERE eliminado_en IS NULL;

-- ----------------------------------------------------------------------------
-- Vehículos
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS vehiculos (
    id           integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    patente      varchar(10) NOT NULL,
    tipo         varchar(20) NOT NULL DEFAULT 'auto'
                 CHECK (tipo IN ('auto','moto','camioneta','discapacidad')),
    marca        varchar(50),
    modelo       varchar(50),
    color        varchar(30),
    cliente_id   integer REFERENCES clientes(id) ON DELETE SET NULL,
    created_at   timestamp with time zone NOT NULL DEFAULT now(),
    eliminado_en timestamp with time zone,
    CONSTRAINT uq_vehiculos_patente UNIQUE (patente)
);

CREATE INDEX IF NOT EXISTS idx_vehiculos_cliente ON vehiculos (cliente_id);
CREATE INDEX IF NOT EXISTS idx_vehiculos_patente ON vehiculos (patente) WHERE eliminado_en IS NULL;

-- ----------------------------------------------------------------------------
-- Plazas de estacionamiento
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS plazas (
    id            integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    numero        varchar(10) NOT NULL,
    sector        varchar(20) NOT NULL DEFAULT 'A',
    tipo_vehiculo varchar(20) NOT NULL DEFAULT 'auto'
                  CHECK (tipo_vehiculo IN ('auto','moto','camioneta','discapacidad')),
    estado        varchar(20) NOT NULL DEFAULT 'libre'
                  CHECK (estado IN ('libre','ocupada','mantenimiento')),
    eliminado_en  timestamp with time zone,
    CONSTRAINT uq_plazas_numero UNIQUE (numero)
);

-- ----------------------------------------------------------------------------
-- Tarifas (vigencia por rango de fechas, por tipo de vehículo)
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS tarifas (
    id            integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    tipo_vehiculo varchar(20) NOT NULL
                  CHECK (tipo_vehiculo IN ('auto','moto','camioneta','discapacidad')),
    tarifa_hora   numeric(14,2) NOT NULL DEFAULT 0 CHECK (tarifa_hora >= 0),
    fecha_desde   date NOT NULL,
    fecha_hasta   date,
    eliminado_en  timestamp with time zone,
    CONSTRAINT tarifas_rango_check CHECK (fecha_hasta IS NULL OR fecha_hasta >= fecha_desde)
);

CREATE INDEX IF NOT EXISTS idx_tarifas_tipo ON tarifas (tipo_vehiculo, fecha_desde);

-- ----------------------------------------------------------------------------
-- Tipos de alquiler (1=Diario, 2=Mensual, 3=Anual)
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS tipos_alquiler (
    id     integer PRIMARY KEY,
    nombre varchar(50) NOT NULL
);

-- ----------------------------------------------------------------------------
-- Contratos de alquiler de plazas
-- estado: SOLO activo / finalizado / cancelado (sin 'inactivo', por decisión)
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS contratos_alquiler (
    id               integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    plaza_id         integer NOT NULL REFERENCES plazas(id),
    cliente_id       integer NOT NULL REFERENCES clientes(id),
    tipo_alquiler_id integer REFERENCES tipos_alquiler(id),
    fecha_inicio     date NOT NULL,
    fecha_fin        date NOT NULL,
    monto_total      numeric(14,2) NOT NULL DEFAULT 0 CHECK (monto_total >= 0),
    cuota_mensual    numeric(14,2) NOT NULL DEFAULT 0 CHECK (cuota_mensual >= 0),
    dia_vencimiento  smallint CHECK (dia_vencimiento BETWEEN 1 AND 28),
    estado           varchar(20) NOT NULL DEFAULT 'activo'
                     CHECK (estado IN ('activo','finalizado','cancelado')),
    created_at       timestamp with time zone NOT NULL DEFAULT now(),
    eliminado_en     timestamp with time zone,
    CONSTRAINT contratos_fechas_check CHECK (fecha_fin >= fecha_inicio)
);

CREATE INDEX IF NOT EXISTS idx_contratos_plaza   ON contratos_alquiler (plaza_id);
CREATE INDEX IF NOT EXISTS idx_contratos_cliente ON contratos_alquiler (cliente_id);
CREATE INDEX IF NOT EXISTS idx_contratos_estado  ON contratos_alquiler (estado) WHERE eliminado_en IS NULL;

-- Dos contratos no cancelados (y no borrados lógicamente) no pueden solaparse
-- en la misma plaza. Los cancelados y los eliminados no bloquean.
DO $do$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'exk_contratos_solapados') THEN
        ALTER TABLE contratos_alquiler ADD CONSTRAINT exk_contratos_solapados
        EXCLUDE USING gist (
            plaza_id WITH =,
            daterange(fecha_inicio, fecha_fin, '[]') WITH &&
        ) WHERE (estado <> 'cancelado' AND eliminado_en IS NULL);
    END IF;
END
$do$;

-- ----------------------------------------------------------------------------
-- Movimientos (ingresos/egresos de vehículos)
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS movimientos (
    id              integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    patente         varchar(10) NOT NULL,
    plaza_id        integer NOT NULL REFERENCES plazas(id),
    hora_entrada    timestamp with time zone NOT NULL DEFAULT now(),
    hora_salida     timestamp with time zone,
    monto_calculado numeric(14,2) NOT NULL DEFAULT 0 CHECK (monto_calculado >= 0),
    monto_pagado    numeric(14,2) NOT NULL DEFAULT 0 CHECK (monto_pagado >= 0),
    estado_pago     varchar(20) NOT NULL DEFAULT 'pendiente'
                    CHECK (estado_pago IN ('pendiente','pagado','deuda')),
    forma_pago      varchar(20),
    created_at      timestamp with time zone NOT NULL DEFAULT now(),
    eliminado_en    timestamp with time zone,
    CONSTRAINT movimientos_salida_check CHECK (hora_salida IS NULL OR hora_salida >= hora_entrada)
);

-- Un único movimiento abierto por plaza (ignora borrados lógicos)
CREATE UNIQUE INDEX IF NOT EXISTS uq_movimientos_plaza_abierto
    ON movimientos (plaza_id)
    WHERE hora_salida IS NULL AND eliminado_en IS NULL;

CREATE INDEX IF NOT EXISTS idx_movimientos_patente      ON movimientos (patente);
CREATE INDEX IF NOT EXISTS idx_movimientos_plaza        ON movimientos (plaza_id);
CREATE INDEX IF NOT EXISTS idx_movimientos_hora_entrada ON movimientos (hora_entrada);
CREATE INDEX IF NOT EXISTS idx_movimientos_hora_salida  ON movimientos (hora_salida);

-- ----------------------------------------------------------------------------
-- Recibos (numeración por secuencia dedicada)
-- ----------------------------------------------------------------------------
CREATE SEQUENCE IF NOT EXISTS recibos_numero_seq START WITH 1 INCREMENT BY 1;

CREATE TABLE IF NOT EXISTS recibos (
    id            integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    numero        integer NOT NULL DEFAULT nextval('recibos_numero_seq'::regclass),
    movimiento_id integer REFERENCES movimientos(id),
    contrato_id   integer REFERENCES contratos_alquiler(id),
    cliente_id    integer REFERENCES clientes(id),
    monto         numeric(14,2) NOT NULL DEFAULT 0 CHECK (monto >= 0),
    forma_pago    varchar(30),
    fecha_emision timestamp with time zone NOT NULL DEFAULT now(),
    enviado_email boolean NOT NULL DEFAULT false,
    eliminado_en  timestamp with time zone,
    CONSTRAINT uq_recibos_numero UNIQUE (numero)
);

ALTER SEQUENCE recibos_numero_seq OWNED BY recibos.numero;

CREATE INDEX IF NOT EXISTS idx_recibos_movimiento ON recibos (movimiento_id);
CREATE INDEX IF NOT EXISTS idx_recibos_contrato   ON recibos (contrato_id);
CREATE INDEX IF NOT EXISTS idx_recibos_cliente    ON recibos (cliente_id);

-- ----------------------------------------------------------------------------
-- Pagos de alquiler (un pago activo por contrato y período; índice único parcial)
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS pagos_alquiler (
    id           integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    contrato_id  integer NOT NULL REFERENCES contratos_alquiler(id),
    periodo      varchar(10) NOT NULL CHECK (periodo ~ '^[0-9]{4}-[0-9]{2}(-[0-9]{2})?$'),
    monto        numeric(14,2) NOT NULL DEFAULT 0 CHECK (monto >= 0),
    fecha_pago   timestamp with time zone NOT NULL DEFAULT now(),
    recibo_id    integer REFERENCES recibos(id),
    estado       varchar(20) NOT NULL DEFAULT 'pagado' CHECK (estado IN ('pagado','anulado')),
    eliminado_en timestamp with time zone
);

-- Un pago por contrato+período; los borrados lógicos liberan el período
CREATE UNIQUE INDEX IF NOT EXISTS uq_pagos_alquiler_periodo
    ON pagos_alquiler (contrato_id, periodo)
    WHERE eliminado_en IS NULL;

CREATE INDEX IF NOT EXISTS idx_pagos_contrato ON pagos_alquiler (contrato_id);

-- ----------------------------------------------------------------------------
-- Deudas
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS deudas (
    id                integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cliente_id        integer NOT NULL REFERENCES clientes(id),
    movimiento_id     integer REFERENCES movimientos(id),
    monto_original    numeric(14,2) NOT NULL DEFAULT 0 CHECK (monto_original >= 0),
    monto_con_interes numeric(14,2) NOT NULL DEFAULT 0 CHECK (monto_con_interes >= 0),
    fecha_vencimiento date,
    estado            varchar(20) NOT NULL DEFAULT 'pendiente'
                      CHECK (estado IN ('pendiente','pagada')),
    created_at        timestamp with time zone NOT NULL DEFAULT now(),
    eliminado_en      timestamp with time zone,
    CONSTRAINT deudas_interes_check CHECK (monto_con_interes >= monto_original)
);

-- Una deuda activa por movimiento (los borrados lógicos no bloquean)
CREATE UNIQUE INDEX IF NOT EXISTS uq_deudas_movimiento
    ON deudas (movimiento_id)
    WHERE movimiento_id IS NOT NULL AND eliminado_en IS NULL;

CREATE INDEX IF NOT EXISTS idx_deudas_cliente_estado ON deudas (cliente_id, estado);
CREATE INDEX IF NOT EXISTS idx_deudas_vencimiento    ON deudas (fecha_vencimiento) WHERE estado = 'pendiente';

-- ----------------------------------------------------------------------------
-- Configuración fiscal (fila única id=1)
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS configuracion_fiscal (
    id                   integer PRIMARY KEY CHECK (id = 1),
    razon_social         varchar(120) NOT NULL DEFAULT '',
    cuit                 varchar(13) NOT NULL DEFAULT ''
                         CHECK (cuit = '' OR cuit ~ '^[0-9]{2}-?[0-9]{8}-?[0-9]$'),
    condicion_iva        varchar(30) NOT NULL DEFAULT 'responsable_inscripto'
                         CHECK (condicion_iva IN ('responsable_inscripto','monotributo','exento')),
    alicuota_iva         numeric(5,2) NOT NULL DEFAULT 21.00 CHECK (alicuota_iva BETWEEN 0 AND 100),
    alicuota_iibb        numeric(5,2) NOT NULL DEFAULT 3.00 CHECK (alicuota_iibb BETWEEN 0 AND 100),
    jurisdiccion_iibb    varchar(60) NOT NULL DEFAULT 'CABA',
    nro_inscripcion_iibb varchar(30),
    punto_venta          smallint NOT NULL DEFAULT 1 CHECK (punto_venta BETWEEN 1 AND 9998),
    email_contador       varchar(120),
    inicio_actividades   date,
    direccion            varchar(150),
    telefono             varchar(30),
    actualizado_en       timestamp with time zone
);

-- ----------------------------------------------------------------------------
-- Categorías de gasto
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS categorias_gasto (
    id          integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre      varchar(60) NOT NULL,
    descripcion varchar(150),
    activa      boolean NOT NULL DEFAULT true,
    CONSTRAINT uq_categorias_gasto_nombre UNIQUE (nombre)
);

-- ----------------------------------------------------------------------------
-- Gastos / compras (libro de compras) — 20 columnas
-- total = neto_gravado + iva_21 + iva_105 + iva_27 + no_gravado
--         + percepcion_iva + percepcion_iibb  (CHECK de coherencia)
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS gastos_compras (
    id                 integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fecha              date NOT NULL,
    proveedor          varchar(120) NOT NULL,
    cuit_proveedor     varchar(13)
                       CHECK (cuit_proveedor IS NULL OR cuit_proveedor ~ '^[0-9]{2}-?[0-9]{8}-?[0-9]$'),
    tipo_comprobante   varchar(20) NOT NULL DEFAULT 'Factura C',
    punto_venta        smallint CHECK (punto_venta IS NULL OR punto_venta BETWEEN 1 AND 9998),
    numero_comprobante integer CHECK (numero_comprobante IS NULL OR numero_comprobante >= 1),
    neto_gravado       numeric(14,2) NOT NULL DEFAULT 0 CHECK (neto_gravado >= 0),
    iva_21             numeric(14,2) NOT NULL DEFAULT 0 CHECK (iva_21 >= 0),
    iva_105            numeric(14,2) NOT NULL DEFAULT 0 CHECK (iva_105 >= 0),
    iva_27             numeric(14,2) NOT NULL DEFAULT 0 CHECK (iva_27 >= 0),
    no_gravado         numeric(14,2) NOT NULL DEFAULT 0 CHECK (no_gravado >= 0),
    percepcion_iva     numeric(14,2) NOT NULL DEFAULT 0 CHECK (percepcion_iva >= 0),
    percepcion_iibb    numeric(14,2) NOT NULL DEFAULT 0 CHECK (percepcion_iibb >= 0),
    total              numeric(14,2) NOT NULL DEFAULT 0,
    categoria_id       integer REFERENCES categorias_gasto(id),
    forma_pago         varchar(20),
    notas              varchar(255),
    created_at         timestamp with time zone NOT NULL DEFAULT now(),
    eliminado_en       timestamp with time zone,
    CONSTRAINT gastos_compras_total_check CHECK (
        total >= 0
        AND total = neto_gravado + iva_21 + iva_105 + iva_27
                     + no_gravado + percepcion_iva + percepcion_iibb
    )
);

CREATE INDEX IF NOT EXISTS idx_gastos_fecha        ON gastos_compras (fecha);
CREATE INDEX IF NOT EXISTS idx_gastos_proveedor    ON gastos_compras (proveedor);
CREATE INDEX IF NOT EXISTS idx_gastos_categoria    ON gastos_compras (categoria_id);
CREATE INDEX IF NOT EXISTS idx_gastos_compras_cuit ON gastos_compras (cuit_proveedor);

-- ----------------------------------------------------------------------------
-- Percepciones / retenciones de IIBB (por período y jurisdicción)
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS percepciones_iibb (
    id           integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    periodo      char(7) NOT NULL CHECK (periodo ~ '^[0-9]{4}-[0-9]{2}$'),
    jurisdiccion varchar(60) NOT NULL DEFAULT 'CABA',
    tipo         varchar(20) NOT NULL DEFAULT 'percepcion'
                 CHECK (tipo IN ('percepcion','retencion')),
    monto        numeric(14,2) NOT NULL DEFAULT 0 CHECK (monto >= 0),
    detalle      varchar(150),
    created_at   timestamp with time zone NOT NULL DEFAULT now(),
    eliminado_en timestamp with time zone
);

CREATE INDEX IF NOT EXISTS idx_percepciones_periodo      ON percepciones_iibb (periodo);
CREATE INDEX IF NOT EXISTS idx_percepciones_jurisdiccion ON percepciones_iibb (jurisdiccion);

-- ----------------------------------------------------------------------------
-- Saldo técnico de IVA anterior por período
-- (saldo_tecnico_anterior > 0 → a favor / crédito; < 0 → a pagar)
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS saldos_iva (
    id                     integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    periodo                char(7) NOT NULL CHECK (periodo ~ '^[0-9]{4}-[0-9]{2}$'),
    saldo_tecnico_anterior numeric(14,2) NOT NULL DEFAULT 0,
    notas                  varchar(255),
    created_at             timestamp with time zone NOT NULL DEFAULT now(),
    CONSTRAINT uq_saldos_iva_periodo UNIQUE (periodo)
);

-- ----------------------------------------------------------------------------
-- Usuarios (autenticación)
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS usuarios (
    id                integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre            varchar(100) NOT NULL,
    email             varchar(150) NOT NULL,
    password_hash     varchar(255) NOT NULL,
    rol               varchar(20) NOT NULL DEFAULT 'operador'
                      CHECK (rol IN ('admin','operador','contador')),
    activo            boolean NOT NULL DEFAULT true,
    intentos_fallidos integer NOT NULL DEFAULT 0 CHECK (intentos_fallidos >= 0),
    ultimo_login      timestamp with time zone,
    bloqueado_hasta   timestamp with time zone,
    creado_en         timestamp with time zone NOT NULL DEFAULT now(),
    actualizado_en    timestamp with time zone NOT NULL DEFAULT now()
);

-- UNIQUE (lower(email)): sin duplicados por mayúsculas/minúsculas
CREATE UNIQUE INDEX IF NOT EXISTS uq_usuarios_email ON usuarios (lower(email));

-- ----------------------------------------------------------------------------
-- Bot asistente: conversaciones
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS bot_conversaciones (
    id            integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    usuario_id    integer REFERENCES usuarios(id),
    sesion_id     varchar(64) NOT NULL DEFAULT '',
    fecha         timestamp with time zone NOT NULL DEFAULT now(),
    pregunta      varchar(300) NOT NULL,
    respuesta     text,
    entrada_id    varchar(60),
    puntaje       numeric(8,2),
    pantalla      varchar(200),
    util          varchar(2) CHECK (util IS NULL OR util IN ('si','no')),
    sin_respuesta boolean NOT NULL DEFAULT false
);

CREATE INDEX IF NOT EXISTS idx_bot_fecha         ON bot_conversaciones (fecha);
CREATE INDEX IF NOT EXISTS idx_bot_sesion        ON bot_conversaciones (sesion_id);
CREATE INDEX IF NOT EXISTS idx_bot_sin_respuesta ON bot_conversaciones (sin_respuesta) WHERE sin_respuesta;
CREATE INDEX IF NOT EXISTS idx_bot_util          ON bot_conversaciones (util);
CREATE INDEX IF NOT EXISTS idx_bot_entrada       ON bot_conversaciones (entrada_id);

-- ----------------------------------------------------------------------------
-- Rate limit (contador por identificador/acción en ventanas de tiempo)
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS rate_limit (
    id            integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    identificador varchar(120) NOT NULL,
    accion        varchar(40) NOT NULL DEFAULT 'bot_pregunta',
    ventana       timestamp with time zone NOT NULL,
    contador      integer NOT NULL DEFAULT 0 CHECK (contador >= 0),
    creado_en     timestamp with time zone NOT NULL DEFAULT now(),
    CONSTRAINT uq_rate_limit_ventana UNIQUE (identificador, accion, ventana)
);

CREATE INDEX IF NOT EXISTS idx_rate_limit_ventana ON rate_limit (ventana);

-- ----------------------------------------------------------------------------
-- Auditoría de cambios (inmutable: triggers de UPDATE/DELETE y TRUNCATE)
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS auditoria_cambios (
    id          bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    usuario_id  integer REFERENCES usuarios(id),
    accion      varchar(20) NOT NULL CHECK (accion IN ('INSERT','UPDATE','DELETE')),
    tabla       varchar(64) NOT NULL,
    registro_id bigint NOT NULL,
    antes       jsonb,
    despues     jsonb,
    ip          inet,
    fecha       timestamp with time zone NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_auditoria_tabla_registro ON auditoria_cambios (tabla, registro_id);
CREATE INDEX IF NOT EXISTS idx_auditoria_fecha          ON auditoria_cambios (fecha);

CREATE OR REPLACE FUNCTION bloquea_auditoria() RETURNS trigger
LANGUAGE plpgsql AS $fn$
BEGIN
    RAISE EXCEPTION 'auditoria_cambios es inmutable: operación % bloqueada por trigger', TG_OP
        USING ERRCODE = 'restrict_violation';
END;
$fn$;

DROP TRIGGER IF EXISTS trg_auditoria_inmutable ON auditoria_cambios;
CREATE TRIGGER trg_auditoria_inmutable
    BEFORE UPDATE OR DELETE ON auditoria_cambios
    FOR EACH ROW EXECUTE FUNCTION bloquea_auditoria();

DROP TRIGGER IF EXISTS trg_auditoria_no_truncate ON auditoria_cambios;
CREATE TRIGGER trg_auditoria_no_truncate
    BEFORE TRUNCATE ON auditoria_cambios
    FOR EACH STATEMENT EXECUTE FUNCTION bloquea_auditoria();

-- Fin de 001_initial_schema.sql
